    setCart((current) => {
      const quantity = (current[product.id]?.quantity ?? 0) + 1;
      if (quantity > 100) return current;
      if (product.kind === "on_hand" && quantity > product.stock) return current;
      return { ...current, [product.id]: { product, quantity } };
    });
  }
  function changeQuantity(product: Product, quantity: number) {
    setCart((current) => {
      if (quantity < 1) { const next = { ...current }; delete next[product.id]; return next; }
      if (quantity > 100) return current;
      if (product.kind === "on_hand" && quantity > product.stock) return current;
      return { ...current, [product.id]: { product, quantity } };
    });
  }
