    const file = event.target.files?.[0];
    if (!file) { setProof(null); return; }
    if (!["image/jpeg", "image/png", "image/webp"].includes(file.type) || file.size > 3 * 1024 * 1024) {
      setCheckoutError("Choose an image under 3 MB."); event.target.value = ""; setProof(null); return;
    }
    const data = await new Promise<string>((resolve, reject) => {
      const reader = new FileReader(); reader.onload = () => resolve(String(reader.result)); reader.onerror = () => reject(new Error("Could not read receipt.")); reader.readAsDataURL(file);
