      <div className="hero-art" aria-label="Shopping basket illustration"><div className="sun-shape"/><div className="flower flower-one">✿</div><div className="flower flower-two">✿</div><div className="bag-art"><div className="bag-handle"/><div className="bag-face"><span>good<br/>finds</span><b>t!</b></div><div className="bag-leaf leaf-a"/><div className="bag-leaf leaf-b"/></div><span className="art-note note-top">on-hand &amp; group buys</span><span className="art-note note-bottom">made for your happy mail ♡</span></div>
      <div className="hero-counter"><b>01</b><span>New batch<br/>open now</span><span className="counter-line"/></div>
    </section>

