pan><b>{money(total.total)}</b></div>{checkoutError && <p className="form-error" role="alert">{checkoutError}</p>}<button className="button primary checkout-button" type="submit" disabled={submitting}>{submitting ? "Sending order…" : "Place order · " + money(total.total)}</button><p className="secure-note">Your order, price, stock and shipping are checked again before it’s saved.</p></form></section></div>}

    {successOrder && <div className="overlay success-overlay"><section className="success-card"><span className="success-heart">♡</span><span className="eyebrow">ORDER SENT</span><h2>You’re on the list!</h2><p>Your order number is <b>{successOrder}</b>. Keep it handy while Tin checks your receipt.</p><Link className="button primary" href={`/track-order?order=${encodeURIComponent(successOrder)}`}>Track your order →</Link><button className="text-button" onClick={() => setSuccessOrder("")}>Back to shopping</button></section></div>}
  </main>;
}
