tchStatus) && <small>Batch: {String(shipment.batchStatus).replaceAll("_", " ")}{shipment.eta ? ` · ETA ${new Intl.DateTimeFormat("en-PH", { dateStyle: "medium" }).format(new Date(String(shipment.eta)))}` : ""}</small>}</div><small>{String(shipment.status ?? "processing").replaceAll("_", " ")}</small></div>)}</div>}{order.total != null && <div className="track-total"><span>Order total</span><b>₱{(Number(order.total) / 100).toLocaleString("en-PH")}</b></div>}</div>}</section><footer className="footer wrap"><Link href="/" className="brand"><span className="brand-mark small-mark">t!</span><span><strong>Tindahan ni Tinapa</strong><small>little finds, happy finds</small></span></Link><p>Made with care for your next favorite thing.</p><span className="copyright">© {new Date().getFullYear()} Tindahan ni Tinapa</span></footer></main>;
}
