    "content": "export function buildShipmentGroups(items, preference) {
  if (preference === "together") {
    return [{ key: "combined", kind: "combined", batchId: null, lines: items, quantity: items.reduce((sum, item) => sum + item.quantity, 0) }];
  }

  const groups = new Map();
  for (const item of items) {
    const kind = item.kind === "on_hand" ? "on_hand" : "group_buy";
    const batchId = kind === "group_buy" ? String(item.batchId) : null;
    const key = kind === "on_hand" ? "on_hand" : `batch:${batchId}`;
    const group = groups.get(key) ?? { key, kind, batchId, lines: [], quantity: 0 };
    group.lines.push(item);
    group.quantity += item.quantity;
    groups.set(key, group);
  }
  return [...groups.values()];
}

export function calculateOrderTotal(items, preference, shippingRate) {
  const subtotal = items.reduce((sum, item) => sum + item.price * item.quantity, 0);
  const shipments = buildShipmentGroups(items, preference).map((group) => ({
    ...group,
    shipping: shippingRate(group.quantity),
  }));
  const shipping = shipments.reduce((sum, shipment) => sum + shipment.shipping, 0);
  return { subtotal, shipping, total: subtotal + shipping, shipments };
}

export function calculateShippingRate(config, region, quantity) {
  const normalized = String(region || "other").trim().toLowerCase();
  let rates = config?.[normalized];
  if (!rates) {
    if (normalized.includes("luzon")) rates = config?.luzon;
    else if (normalized.includes("visaya")) rates = config?.visayas;
    else if (normalized.includes("mindanao")) rates = config?.mindanao;
    else rates = config?.other;
  }
  if (!rates) return 0;
  if (quantity <= 1) return Number(rates["1"] ?? 0);
  if (quantity === 2) return Number(rates["2"] ?? 0);
  return Number(rates.max ?? 0);
}

export function isBatchOrderable(batch, now = new Date()) {
  return batch.status === "open" && new Date(batch.deadline).getTime() > now.getTime();
}
