  "arguments": {
    "content": "import type { Metadata } from "next";
import Link from "next/link";
import { db } from "@/lib/db";
import { orders, orderItems } from "@/lib/db/schema";
import { desc, gte, eq, and } from "drizzle-orm";
import { formatPrice } from "@/lib/utils";
import RevenueChart from "@/components/dashboard/revenue-chart";
import { BarChart3, TrendingUp, ShoppingBag, Award } from "lucide-react";
import AnalyticsRangeFilter from "@/components/dashboard/analytics-range-filter";

export const metadata: Metadata = {
  title: "Analytics — SellerHub",
};

export const dynamic = "force-dynamic";

interface PageProps {
  searchParams: Promise<{ range?: string }>;
}

export default async function AdminAnalyticsPage({ searchParams }: PageProps) {
  const { range = "week" } = await searchParams;

  let startDate: Date | null = new Date();
  if (range === "today") {
    startDate.setHours(0, 0, 0, 0);
  } else if (range === "week") {
    startDate.setDate(startDate.getDate() - 7);
  } else if (range === "month") {
    startDate.setMonth(startDate.getMonth() - 1);
  } else {
    startDate = null; // all time
  }

  const allOrders = await db.query.orders.findMany({
    where: startDate ? and(eq(orders.storefrontKey, "main"), gte(orders.createdAt, startDate)) : eq(orders.storefrontKey, "main"),
    with: {
      orderItems: true,
    },
    orderBy: [desc(orders.createdAt)],
  });

  const totalOrdersCount = allOrders.length;
  const paidOrders = allOrders.filter((o) => o.paymentStatus === "paid");
  const totalRevenueCents = paidOrders.reduce((sum, o) => sum + o.total, 0);
  const avgOrderValueCents =
    paidOrders.length > 0 ? Math.round(totalRevenueCents / paidOrders.length) : 0;

  // Aggregate top products
  const productStatsMap = new Map<
    string,
    { name: string; quantity: number; revenue: number }
  >();

  for (const o of paidOrders) {
    if (o.orderItems) {
      for (const item of o.orderItems) {
        const existing = productStatsMap.get(item.productName);
        if (existing) {
          existing.quantity += item.quantity;
          existing.revenue += item.subtotal;
        } else {
          productStatsMap.set(item.productName, {
            name: item.productName,
            quantity: item.quantity,
            revenue: item.subtotal,
          });
        }
      }
    }
  }

  const topProducts = Array.from(productStatsMap.values())
    .sort((a, b) => b.quantity - a.quantity)
    .slice(0, 5);

  // Group revenue by date for chart
  const dateMap = new Map<string, { date: string; revenue: number; orders: number }>();

  // Fill in past dates for smooth chart
  const daysToInclude = range === "today" ? 1 : range === "week" ? 7 : 30;
  for (let i = daysToInclude - 1; i >= 0; i--) {
    const d = new Date();
    d.setDate(d.getDate() - i);
    const dateStr = d.toLocaleDateString("en-US", { month: "short", day: "numeric" });
    dateMap.set(dateStr, { date: dateStr, revenue: 0, orders: 0 });
  }

  for (const o of allOrders) {
    const dateStr = new Date(o.createdAt).toLocaleDateString("en-US", {
      month: "short",
      day: "numeric",
    });

    const entry = dateMap.get(dateStr) ?? { date: dateStr, revenue: 0, orders: 0 };
    entry.orders += 1;
    if (o.paymentStatus === "paid") {
      entry.revenue += o.total;
    }
    dateMap.set(dateStr, entry);
  }

  const chartData = Array.from(dateMap.values());

  return (
    <div className="px-4 py-6 md:px-8 space-y-6">
      {/* Header & Filter */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-[var(--color-text-primary)]">
            Sales &amp; Performance Analytics
          </h1>
          <p className="text-xs text-[var(--color-text-secondary)] mt-0.5">
            Track revenue, orders, and popular product performance.
          </p>
        </div>
        <AnalyticsRangeFilter activeRange={range} />
      </div>

      {/* Metrics Grid */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="neu-card p-4 space-y-1">
          <p className="text-xs font-semibold uppercase text-[var(--color-text-secondary)]">
            Total Sales Revenue
          </p>
          <p className="text-2xl font-extrabold text-[var(--color-accent)]">
            {formatPrice(totalRevenueCents)}
          </p>
        </div>

        <div className="neu-card p-4 space-y-1">
          <p className="text-xs font-semibold uppercase text-[var(--color-text-secondary)]">
            Total Orders
          </p>
          <p className="text-2xl font-extrabold text-[var(--color-text-primary)]">
            {totalOrdersCount}
          </p>
        </div>

        <div className="neu-card p-4 space-y-1">
          <p className="text-xs font-semibold uppercase text-[var(--color-text-secondary)]">
            Paid Orders
          </p>
          <p className="text-2xl font-extrabold text-[var(--color-status-success)]">
            {paidOrders.length}
          </p>
        </div>

        <div className="neu-card p-4 space-y-1">
          <p className="text-xs font-semibold uppercase text-[var(--color-text-secondary)]">
            Avg. Order Value
          </p>
          <p className="text-2xl font-extrabold text-[var(--color-text-primary)]">
            {formatPrice(avgOrderValueCents)}
          </p>
        </div>
      </div>

      {/* Sales Revenue Chart */}
      <div className="neu-card p-5 space-y-4">
        <h2 className="text-base font-bold text-[var(--color-text-primary)] flex items-center gap-2">
          <TrendingUp size={18} className="text-[var(--color-accent)]" />
          Revenue Trend
        </h2>
        <RevenueChart data={chartData} />
      </div>

      {/* Top Products */}
      <div className="neu-card p-5 space-y-4">
        <h2 className="text-base font-bold text-[var(--color-text-primary)] flex items-center gap-2">
          <Award size={18} className="text-[var(--color-accent)]" />
          Top Selling Products
        </h2>

        {topProducts.length === 0 ? (
          <div className="text-center py-6 text-xs text-[var(--color-text-muted)]">
            No product sales recorded in this timeframe yet.
          </div>
        ) : (
          <div className="space-y-3">
            {topProducts.map((p, idx) => (
              <div
                key={p.name}
                className="flex items-center justify-between p-3 rounded-xl bg-[var(--color-neu-bg)] text-xs"
              >
                <div className="flex items-center gap-3">
                  <span className="w-6 h-6 rounded-full bg-[var(--color-accent-light)] text-[var(--color-accent)] font-bold flex items-center justify-center">
                    #{idx + 1}
                  </span>
                  <div>
                    <p className="font-bold text-sm text-[var(--color-text-primary)]">
                      {p.name}
                    </p>
                    <p className="text-[var(--color-text-secondary)]">
                      {p.quantity} units sold
                    </p>
                  </div>
                </div>
                <span className="font-bold text-sm text-[var(--color-accent)]">
                  {formatPrice(p.revenue)}
                </span>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
