    "content": "import type { Metadata } from "next";
import Link from "next/link";
import { notFound, redirect } from "next/navigation";
import { ArrowLeft, Check, X, MessageSquare, Package, User, MapPin, CreditCard } from "lucide-react";
import { db } from "@/lib/db";
import { auth } from "@/auth";
import { OrderStatusBadge, PaymentStatusBadge } from "@/components/ui/status-badge";
import PaymentProofViewer from "@/components/orders/payment-proof-viewer";
import OrderTimeline from "@/components/orders/order-timeline";
import { formatPrice, formatDateTime } from "@/lib/utils";
import { getProductByName, getProductById } from "@/lib/products";
import {
  confirmPayment,
  rejectPayment,
  updateOrderStatus,
  addOrderNote,
} from "@/lib/actions/admin-orders";
import OrderStatusUpdater from "@/components/orders/order-status-updater";
import PaymentVerifierActions from "@/components/orders/payment-verifier-actions";
import DeleteOrderButton from "@/components/orders/delete-order-button";
import { updateTindahanShipment } from "@/lib/actions/group-buy";

export const metadata: Metadata = {
  title: "Order Details — SellerHub",
};

export const dynamic = "force-dynamic";

interface PageProps {
  params: Promise<{ id: string }>;
}

export default async function AdminOrderDetailPage({ params }: PageProps) {
  const session = await auth();
  if (!session?.user) redirect("/admin/login");

  const { id } = await params;
  const orderId = parseInt(id, 10);

  if (isNaN(orderId)) notFound();

  const order = await db.query.orders.findFirst({
    where: (o, { eq }) => eq(o.id, orderId),
    with: {
      orderItems: true,
      shipments: { with: { batch: true } },
      orderEvents: {
        orderBy: (events, { desc }) => [desc(events.createdAt)],
      },
    },
  });

