import OrderCard from "@/components/orders/order-card";
import SearchBar from "@/components/ui/search-bar";
import { OrderStatusBadge, PaymentStatusBadge } from "@/components/ui/status-badge";
import { formatPrice, formatDateTime } from "@/lib/utils";
import FilterTabs from "@/components/orders/filter-tabs";

export const metadata: Metadata = {
  title: "Orders — SellerHub",
};

export const dynamic = "force-dynamic";

interface PageProps {
  searchParams: Promise<{
    search?: string;
    status?: string;
    page?: string;
  }>;
}

export default async function AdminOrdersPage({ searchParams }: PageProps) {
  const { search = "", status = "all", page = "1" } = await searchParams;
  const currentPage = Math.max(1, parseInt(page, 10));
  const pageSize = 20;
  const offset = (currentPage - 1) * pageSize;

  // Build filter conditions
  const conditions = [];
  conditions.push(eq(orders.storefrontKey, "main"));

  if (search.trim()) {
    const term = `%${search.trim()}%`;
    conditions.push(
      or(
        like(orders.orderNumber, term),
        like(orders.customerName, term),
        like(orders.customerPhone, term)
      )
    );
  }

  if (status !== "all") {
    if (status === "under_verification") {
      conditions.push(eq(orders.paymentStatus, "under_verification"));
    } else if (status === "paid_payment") {
      conditions.push(eq(orders.paymentStatus, "paid"));
    } else {
      conditions.push(eq(orders.orderStatus, status as any));
    }
  }

  const whereClause = conditions.length > 0 ? sql.join(conditions, sql` AND `) : undefined;

  const orderList = await db.query.orders.findMany({
    where: whereClause,
    orderBy: [desc(orders.createdAt)],
    limit: pageSize,
    offset: offset,
  });

  return (
    <div className="px-4 py-6 md:px-8 space-y-6">
      {/* Header */}
      <div>
        <h1 className="text-2xl font-bold text-[var(--color-text-primary)]">
          Orders Management
        </h1>
        <p className="text-xs text-[var(--color-text-secondary)] mt-0.5">
          View, search, and process customer orders.
        </p>
      </div>

      {/* Search & Filters */}
      <div className="space-y-4">
        <FilterTabs activeStatus={status} search={search} />
      </div>

      {/* Orders Output */}
      {orderList.length === 0 ? (
        <div className="neu-card p-12 text-center text-sm text-[var(--color-text-secondary)]">
          No orders found matching your filter criteria.
        </div>
      ) : (
        <>
          {/* Mobile View: Cards */}
          <div className="grid gap-3 md:hidden">
            {orderList.map((order) => (
              <OrderCard key={order.id} order={order} />
            ))}
          </div>

          {/* Desktop View: Table */}
          <div className="hidden md:block neu-card p-0 overflow-hidden">
            <table className="w-full text-left text-sm">
              <thead className="bg-[var(--color-neu-bg)] text-xs uppercase font-semibold text-[var(--color-text-secondary)] border-b border-[var(--color-neu-shadow-dark)]/30">
                <tr>
                  <th className="p-4">Order #</th>
                  <th className="p-4">Customer</th>
                  <th className="p-4">Total</th>
                  <th className="p-4">Payment</th>
                  <th className="p-4">Order Status</th>
                  <th className="p-4">Date</th>
                  <th className="p-4 text-right">Action</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-[var(--color-neu-shadow-dark)]/20">
                {orderList.map((order) => (
                  <tr
                    key={order.id}
                    className="hover:bg-[var(--color-accent-muted)]/30 transition-colors"
                  >
                    <td className="p-4 font-bold text-[var(--color-accent)]">
                      {order.orderNumber}
                    </td>
                    <td className="p-4">
                      <div className="font-semibold text-[var(--color-text-primary)]">
                        {order.customerName}
                      </div>
                      <div className="text-xs text-[var(--color-text-secondary)]">
                        {order.customerPhone}
                      </div>
                    </td>
                    <td className="p-4 font-bold text-[var(--color-text-primary)]">
                      {formatPrice(order.total)}
                    </td>
                    <td className="p-4">
                      <PaymentStatusBadge status={order.paymentStatus} />
                    </td>
                    <td className="p-4">
                      <OrderStatusBadge status={order.orderStatus} />
                    </td>
                    <td className="p-4 text-xs text-[var(--color-text-secondary)]">
                      {formatDateTime(order.createdAt)}
                    </td>
                    <td className="p-4 text-right">
                      <Link
                        href={`/admin/orders/${order.id}`}
                        className="neu-button neu-button-accent text-xs px-3 py-1.5 rounded-lg"
                      >
                        Details
                      </Link>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </>
      )}
    </div>
  );
}
