    "content": "import type { Metadata } from "next";
import Link from "next/link";
import { auth } from "@/auth";
import { redirect } from "next/navigation";
import { db } from "@/lib/db";
import { orders } from "@/lib/db/schema";
import { desc, eq } from "drizzle-orm";
import { formatDateTime, formatPrice } from "@/lib/utils";
import { OrderStatusBadge, PaymentStatusBadge } from "@/components/ui/status-badge";

export const metadata: Metadata = { title: "Group Buy Orders — SellerHub" };
export const dynamic = "force-dynamic";

export default async function GroupBuyOrdersPage() {
  const session = await auth();
  if (!session?.user) redirect("/admin/login");
  const orderList = await db.query.orders.findMany({
    where: eq(orders.storefrontKey, "tindahan"),
    with: { orderItems: true, shipments: { with: { batch: true } } },
    orderBy: [desc(orders.createdAt)],
    limit: 100,
  });

  return <div className="px-4 py-6 md:px-8 space-y-6">
    <header className="flex flex-wrap items-end justify-between gap-3">
      <div><h1 className="text-2xl font-bold">Group-buy orders</h1><p className="mt-1 text-sm text-[var(--color-text-secondary)]">Tindahan ni Tinapa orders, receipts, batches, and parcels.</p></div>
      <Link href="/admin/group-buy" className="neu-button neu-button-accent rounded-xl px-4 py-2 text-sm font-bold">Manage catalog and batches</Link>
    </header>
    {orderList.length === 0 ? <div className="neu-card p-12 text-center text-sm text-[var(--color-text-secondary)]">No group-buy orders yet.</div> : <div className="space-y-3">
      {orderList.map((order) => <article key={order.id} className="neu-card grid gap-4 p-4 lg:grid-cols-[1fr_1fr_auto] lg:items-center">
        <div className="space-y-1">
          <Link href={`/admin/orders/${order.id}`} className="font-bold text-[var(--color-accent)] hover:underline">{order.orderNumber}</Link>
          <p className="text-sm font-semibold">{order.customerName} · {order.customerPhone}</p>
          <p className="text-xs text-[var(--color-text-secondary)]">{formatDateTime(order.createdAt)}</p>
          <p className="text-xs text-[var(--color-text-secondary)]">{order.orderItems.map((item) => `${item.productName} ×${item.quantity}`).join(" · ")}</p>
        </div>
        <div className="space-y-2 text-xs">
          {order.shipments.map((shipment) => <div key={shipment.id} className="rounded-xl border border-black/10 px-3 py-2">
            <p className="font-bold">{shipment.kind === "on_hand" ? "On-hand parcel" : shipment.kind === "combined" ? "Combined parcel" : `Group-buy parcel · ${shipment.batch?.name || "Batch"}`}</p>
            <p className="text-[var(--color-text-secondary)]">{shipment.status.replaceAll("_", " ")} · {formatPrice(shipment.shippingFee)}</p>
            {shipment.batch && <p className="text-[var(--color-text-secondary)]">Batch: {shipment.batch.status} · ETA {shipment.batch.eta ? formatDateTime(shipment.batch.eta) : "not set"}</p>}
          </div>)}
        </div>
        <div className="flex items-center gap-3 lg:flex-col lg:items-end">
          <div className="flex flex-wrap gap-2"><PaymentStatusBadge status={order.paymentStatus} /><OrderStatusBadge status={order.orderStatus} /></div>
          <p className="font-bold">{formatPrice(order.total)}</p>
          <Link href={`/admin/orders/${order.id}`} className="neu-button rounded-xl px-3 py-1.5 text-xs font-bold">Review receipt</Link>
        </div>
      </article>)}
    </div>}
  </div>;
}
