      }).catch((error) => console.warn("Group-buy notification failed:", error));
    } catch (error) {
      console.warn("Could not load push service:", error);
    }

    return NextResponse.json({ success: true, orderId: created.id, orderNumber: created.orderNumber }, { status: 201, headers: corsHeaders() });
  } catch (error: any) {
    const message = error?.message || "Could not place order.";
    const clientError = /cart is empty|invalid cart item|not enough stock|no longer available|batch.*closed|shipping is unavailable|valid shipping region|maximum quantity|supported payment limit|invalid price|price .* too high/i.test(message);
    return NextResponse.json({ success: false, error: message }, { status: clientError ? 400 : 500, headers: corsHeaders() });
  }
}

// CORS Headers helper
function corsHeaders() {
  return {
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type, Authorization",
  };
}

export async function OPTIONS() {
  return new NextResponse(null, {
    status: 204,
    headers: corsHeaders(),
  });
}

export async function GET(request: NextRequest) {
  try {
    const latest = await db.query.orders.findFirst({
      where: eq(orders.storefrontKey, "main"),
      orderBy: [desc(orders.id)],
      columns: {
        id: true,
        orderNumber: true,
        customerName: true,
        total: true,
        orderStatus: true,
        paymentStatus: true,
        createdAt: true,
      },
    });

    return NextResponse.json(
      {
        success: true,
        latestOrder: latest || null,
        timestamp: Date.now(),
      },
      { headers: corsHeaders() }
    );
  } catch (error: any) {
    return NextResponse.json(
      { success: false, error: error.message },
      { status: 500, headers: corsHeaders() }
    );
  }
}

export async function POST(request: NextRequest) {
  try {
    const body = await request.json().catch(() => null);

    if (!body) {
      return NextResponse.json(
        { success: false, error: "Invalid JSON payload." },
        { status: 400, headers: corsHeaders() }
      );
    }

    if (body.storefrontKey === "tindahan") return await createTindahanOrder(body);

    // Extract fields with alias fallback support
    const customerName = String(
      body.customerName || body.name || body.recipient || ""
    ).trim();
    const customerPhone = String(
      body.customerPhone || body.phone || body.contactNumber || ""
    ).trim();
    const deliveryAddress = String(
      body.deliveryAddress || body.address || body.street || ""
    ).trim();
    const city = String(body.city || "Metro Manila").trim();
    const province = String(body.province || "Metro Manila").trim();
    const customerEmail = body.customerEmail || body.email || null;
    const postalCode = body.postalCode || null;

    const shippingMethodName = String(
      body.shippingMethod || body.shipping || "Standard Shipping"
    ).trim();
    const rawShippingFee = Number(body.shippingFee ?? 0);

    const paymentMethod = String(body.paymentMethod || "GCash").trim();
    const notes = body.notes || body.specialInstructions || body.remarks || null;

    // Validate required customer info
    if (!customerName) {
      return NextResponse.json(
        { success: false, error: "customerName is required." },
        { status: 400, headers: corsHeaders() }
      );
    }
    if (!customerPhone) {
      return NextResponse.json(
        { success: false, error: "customerPhone is required." },
        { status: 400, headers: corsHeaders() }
      );
    }
    if (!deliveryAddress) {
      return NextResponse.json(
        { success: false, error: "deliveryAddress is required." },
        { status: 400, headers: corsHeaders() }
      );
    }

    // Validate items array
    const rawItems = Array.isArray(body.items) ? body.items : [];
    if (rawItems.length === 0) {
      return NextResponse.json(
        { success: false, error: "At least one item is required." },
        { status: 400, headers: corsHeaders() }
      );
    }

    // Process & calculate items
    const parsedLineItems: Array<{
      productId: string | null;
      productName: string;
      unitPrice: number;
      quantity: number;
      subtotal: number;
    }> = [];

    let calculatedSubtotalInCents = 0;
    let totalItemCount = 0;

    for (const rawItem of rawItems) {
      const quantity = Math.max(1, Number(rawItem.quantity || 1));
      totalItemCount += quantity;

      const rawItemName = String(
        rawItem.name || rawItem.productName || rawItem.id || "Product Item"
      ).trim();

      // Lookup product reference if available
      const matched =
        (rawItem.id ? getProductById(rawItem.id) : undefined) ||
        getProductByName(rawItem.name || rawItem.productName || "");

      const officialName = matched?.fullName || matched?.name || rawItemName;
      const rawPrice = Number(
        rawItem.price ?? rawItem.unitPrice ?? matched?.price ?? 0
      );

      // Convert unit price to cents if < 100000
      const unitPriceInCents =
        rawPrice > 0 && rawPrice < 100000
          ? Math.round(rawPrice * 100)
          : Math.round(rawPrice);

      const itemSubtotal = unitPriceInCents * quantity;
      calculatedSubtotalInCents += itemSubtotal;

      parsedLineItems.push({
        productId: matched?.id ? String(matched.id) : null,
        productName: officialName,
        unitPrice: unitPriceInCents,
        quantity,
        subtotal: itemSubtotal,
      });
    }

    // Validate & compute tiered shipping fee from products.json shipping_config
    const calculatedTieredShippingFeePesos = calculateShippingFee(
      shippingMethodName || province || city,
      totalItemCount
    );

    // Determine final shipping fee in cents
    const shippingFeeInCents =
      rawShippingFee > 0
        ? rawShippingFee < 10000
          ? Math.round(rawShippingFee * 100)
          : Math.round(rawShippingFee)
        : Math.round(calculatedTieredShippingFeePesos * 100);

    const totalInCents = calculatedSubtotalInCents + shippingFeeInCents;

    // Parse & resolve payment proof Google Drive file ID
    let resolvedProofFileId: string | null = null;

    const base64DataStr =
      typeof body.imageData === "string" && body.imageData.startsWith("data:image/")
        ? body.imageData
        : typeof body.paymentProofUrl === "string" && body.paymentProofUrl.startsWith("data:image/")
        ? body.paymentProofUrl
        : null;

    const urlOrIdCandidate = String(body.driveUrl || body.paymentProofUrl || body.paymentProofFileId || "").trim();
    const driveUrlMatch = urlOrIdCandidate.match(/\/d\/([a-zA-Z0-9_-]+)/);

    if (driveUrlMatch) {
      resolvedProofFileId = driveUrlMatch[1];
    } else if (/^[a-zA-Z0-9_-]{25,50}$/.test(urlOrIdCandidate) && !urlOrIdCandidate.includes(".")) {
      resolvedProofFileId = urlOrIdCandidate;
    } else if (base64DataStr) {
      // Direct base64 image data URL uploaded from client: upload to Google Drive via Service Account
      try {
        const match = base64DataStr.match(/^data:(image\/\w+);base64,(.+)$/);
        if (match) {
          const mimeType = match[1];
          const base64Data = match[2];
          const buffer = Buffer.from(base64Data, "base64");
          const ext = mimeType.split("/")[1] || "png";
          const clientName = typeof body.imageName === "string" && body.imageName.trim() ? body.imageName.trim() : null;
          const filename = clientName || `proof_${Date.now()}.${ext}`;
          const uploadRes = await uploadPaymentProof(buffer, mimeType, filename);
          resolvedProofFileId = uploadRes.fileId;
        }
      } catch (uploadErr) {
        console.warn("Direct base64 Google Drive upload fallback notice:", uploadErr);
      }
    } else if (urlOrIdCandidate && urlOrIdCandidate !== "uploaded_receipt") {
      // Fallback: search Drive by filename if provided
      try {
        const { google } = await import("googleapis");
        const email = process.env.GOOGLE_CLIENT_EMAIL || process.env.GOOGLE_SERVICE_ACCOUNT_EMAIL;
        const privateKey = process.env.GOOGLE_PRIVATE_KEY || process.env.GOOGLE_SERVICE_ACCOUNT_PRIVATE_KEY;
        if (email && privateKey) {
          const auth = new google.auth.GoogleAuth({
            credentials: {
              client_email: email,
              private_key: privateKey.replace(/\\n/g, "\n"),
            },
            scopes: ["https://www.googleapis.com/auth/drive"],
          });
          const drive = google.drive({ version: "v3", auth });
          const list = await drive.files.list({
            q: `name = '${urlOrIdCandidate.replace(/'/g, "\\'")}' and trashed = false`,
            fields: "files(id, name)",
            pageSize: 1,
          });
          if (list.data.files && list.data.files.length > 0 && list.data.files[0].id) {
            resolvedProofFileId = list.data.files[0].id;
          } else {
            resolvedProofFileId = urlOrIdCandidate;
          }
        } else {
          resolvedProofFileId = urlOrIdCandidate;
        }
      } catch {
        resolvedProofFileId = urlOrIdCandidate;
      }
    }

    const hasProof = Boolean(resolvedProofFileId && resolvedProofFileId.trim() !== "");

    // Generate next Order Number sequence using Drizzle query
    const lastOrder = await db.query.orders.findFirst({
      orderBy: [desc(orders.id)],
      columns: { id: true },
    });
    const nextSeq = (lastOrder?.id ?? 0) + 1;
    const prefix = process.env.ORDER_NUMBER_PREFIX ?? "PB";
    const year = new Date().getFullYear();
    const padded = String(nextSeq).padStart(4, "0");
    const orderNumber = `${prefix}-${year}-${padded}`;

    // 1. Insert main order
    const [newOrder] = await db
      .insert(orders)
      .values({
        orderNumber,
        customerName,
        customerPhone,
        customerEmail,
        deliveryAddress,
        city,
        province,
        postalCode,
        shippingMethod: shippingMethodName,
        shippingFee: shippingFeeInCents,
        paymentMethod,
        paymentProofFileId: hasProof ? resolvedProofFileId : null,
        paymentStatus: hasProof ? "under_verification" : "pending",
        orderStatus: hasProof ? "payment_verification" : "pending_payment",
        subtotal: calculatedSubtotalInCents,
        total: totalInCents,
        notes,
      })
      .returning();

    // 2. Insert line items
    await db.insert(orderItems).values(
      parsedLineItems.map((item) => ({
        ...item,
        orderId: newOrder.id,
      }))
    );

    // 3. Record initial events
    await db.insert(orderEvents).values({
      orderId: newOrder.id,
      eventType: "order_submitted",
      description: "Order submitted by customer.",
    });

    if (hasProof) {
      await db.insert(orderEvents).values({
        orderId: newOrder.id,
        eventType: "payment_proof_uploaded",
        description: "Payment proof attached with order.",
      });
    }

    // 4. Trigger background Web Push notification to all registered phones and devices
    try {
      const { sendPushNotificationToAll } = await import("@/lib/push/service");
      sendPushNotificationToAll({
        title: "🌸 New Order Received!",
        body: `Order #${newOrder.orderNumber} from ${newOrder.customerName} (₱${(newOrder.total / 100).toLocaleString()})`,
        url: `/admin/orders/${newOrder.id}`,
        tag: `order-${newOrder.id}`,
      }).catch((pushErr) => {
        console.warn("Background Web Push trigger error:", pushErr);
      });
    } catch (e) {
      console.warn("Could not load push service:", e);
    }

    return NextResponse.json(
      {
        success: true,
        orderId: newOrder.id,
        orderNumber: newOrder.orderNumber,
        message: "Order placed successfully",
      },
      { status: 201, headers: corsHeaders() }
    );
  } catch (error: any) {
    console.error("Public customer intake order API error:", error);
    return NextResponse.json(
      {
        success: false,
        error: error.message || "Failed to process customer order intake.",
      },
      { status: 500, headers: corsHeaders() }
    );
  }
}
