import { db } from "@/lib/db";
import { categories, products, appSettings, groupBuyBatches } from "@/lib/db/schema";
import { eq, asc, and, inArray } from "drizzle-orm";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type, Authorization",
};

export async function OPTIONS() {
  return new NextResponse(null, {
    status: 204,
    headers: corsHeaders,
  });
}

export async function GET(request: Request) {
  try {
    const storefront = new URL(request.url).searchParams.get("storefront") === "tindahan"
      ? "tindahan"
      : "main";
    // 1. Fetch active categories ordered by sortOrder
    const dbCategories = await db.query.categories.findMany({
      where: and(eq(categories.isActive, true), eq(categories.storefrontKey, storefront)),
      orderBy: [asc(categories.sortOrder), asc(categories.createdAt)],
    });

    // 2. Fetch available products ordered by sortOrder
    const dbProducts = await db.query.products.findMany({
      where: and(eq(products.isAvailable, true), eq(products.storefrontKey, storefront)),
      orderBy: [asc(products.sortOrder), asc(products.createdAt)],
    });

    if (storefront === "tindahan") {
      const batchIds = [...new Set(dbProducts.map((product) => product.batchId).filter((id): id is number => id !== null))];
      const dbBatches = batchIds.length
        ? await db.query.groupBuyBatches.findMany({ where: inArray(groupBuyBatches.id, batchIds) })
        : [];
      const now = Date.now();
      const batches = dbBatches.map((batch) => ({
        ...batch,
        status: batch.status === "open" && batch.deadline.getTime() <= now ? "closed" : batch.status,
      }));
      const shippingConfigRecord = await db.query.appSettings.findFirst({
        where: eq(appSettings.key, "shipping_config"),
      });

      return NextResponse.json({
        categories: dbCategories.map((category) => ({
          id: category.id,
          name: category.name,
          icon: category.icon || "📦",
          pill: category.pill || "",
        })),
        products: dbProducts.map((product) => ({
          id: product.id,
          categoryId: product.categoryId,
          name: product.name,
          fullName: product.fullName,
          price: product.price,
          compareAtPrice: product.compareAtPrice,
          description: product.description,
          imageUrl: product.imageUrl,
          emoji: product.emoji || "📦",
          stock: product.stock,
          kind: product.kind,
          batchId: product.batchId,
          batch: batches.find((batch) => batch.id === product.batchId) ?? null,
        })),
        batches,
        shippingConfig: shippingConfigRecord?.value ?? {},
      }, {
        status: 200,
        headers: { ...corsHeaders, "Cache-Control": "public, s-maxage=30, stale-while-revalidate=60" },
      });
    }

    // Group products by categoryId
    const productsByCat = new Map<string, typeof dbProducts>();
    for (const prod of dbProducts) {
      if (!prod.categoryId) continue;
      if (!productsByCat.has(prod.categoryId)) {
        productsByCat.set(prod.categoryId, []);
      }
      productsByCat.get(prod.categoryId)!.push(prod);
    }

    // 3. Assemble category payload matching products.json 1:1
    const catalog = dbCategories
      .map((cat) => {
        const catProducts = productsByCat.get(cat.id) || [];
        return {
          category: cat.name,
          icon: cat.icon || "💉",
          pill: cat.pill || "",
          items: catProducts.map((p) => ({
            id: p.id,
            name: p.name,
            fullName: p.fullName,
            price: p.price,
            emoji: p.emoji || "💉",
          })),
        };
      })
      .filter((cat) => cat.items.length > 0);

    // 4. Fetch shipping_config from appSettings
    const shippingConfigRecord = await db.query.appSettings.findFirst({
      where: eq(appSettings.key, "shipping_config"),
    });

    if (shippingConfigRecord?.value) {
      catalog.push(shippingConfigRecord.value as any);
    }

    return NextResponse.json(catalog, {
      status: 200,
      headers: {
        ...corsHeaders,
        "Cache-Control": "public, s-maxage=30, stale-while-revalidate=60",
      },
    });
  } catch (error: any) {
    console.error("Failed to fetch dynamic products catalog:", error);
    return NextResponse.json(
      { error: "Failed to load products catalog", message: error?.message },
      {
        status: 500,
        headers: corsHeaders,
      }
    );
  }
}
