    "content": "import { NextRequest, NextResponse } from "next/server";
import { eq } from "drizzle-orm";
import { db } from "@/lib/db";
import { orders } from "@/lib/db/schema";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type",
};

export async function OPTIONS() {
  return new NextResponse(null, { status: 204, headers: corsHeaders });
}

export async function POST(request: NextRequest) {
  const body = await request.json().catch(() => null);
  const orderNumber = String(body?.orderNumber || "").trim();
  const phone = String(body?.phone || "").replace(/\D/g, "");
  if (!orderNumber || phone.length < 7) {
    return NextResponse.json({ error: "Enter order number and phone number." }, { status: 400, headers: corsHeaders });
  }

  const order = await db.query.orders.findFirst({
    where: eq(orders.orderNumber, orderNumber),
    with: {
      orderItems: { columns: { productName: true, productKind: true, quantity: true, subtotal: true } },
      shipments: { with: { batch: { columns: { name: true, status: true, deadline: true, eta: true } }, items: { columns: { productName: true, quantity: true } } } },
    },
  });

  if (!order || order.storefrontKey !== "tindahan" || order.customerPhone.replace(/\D/g, "") !== phone) {
    return NextResponse.json({ error: "No matching group-buy order found." }, { status: 404, headers: corsHeaders });
  }

  return NextResponse.json({
    success: true,
    orderNumber: order.orderNumber,
    createdAt: order.createdAt,
    paymentStatus: order.paymentStatus,
    orderStatus: order.orderStatus,
    subtotal: order.subtotal,
    shippingFee: order.shippingFee,
    total: order.total,
    items: order.orderItems,
    shipments: order.shipments.map((shipment) => ({
      kind: shipment.kind,
      status: shipment.status,
      shippingFee: shipment.shippingFee,
      batchName: shipment.batch?.name ?? null,
      batchStatus: shipment.batch?.status === "open" && shipment.batch.deadline.getTime() <= Date.now() ? "closed" : shipment.batch?.status ?? null,
      batchDeadline: shipment.batch?.deadline ?? null,
      eta: shipment.batch?.eta ?? null,
      items: shipment.items,
    })),
  }, { headers: corsHeaders, status: 200 });
}
