                <span
                  className={cn(
                    "text-[10px] tracking-tight leading-tight",
                    active ? "font-bold text-[var(--color-accent-dark)]" : "font-medium"
                  )}
                >
                  {label}
                </span>
              </Link>
            </li>
          );
        })}
      </ul>
    </nav>
  );
}
