import { auth, signOut } from "@/auth";
import {
  LayoutDashboard,
  ShoppingBag,
  Package,
  Boxes,
  BarChart2,
  Settings,
  LogOut,
} from "lucide-react";
import { cn } from "@/lib/utils";
import { headers } from "next/headers";

interface NavLink {
  href: string;
  label: string;
  icon: React.ComponentType<{ size?: number; strokeWidth?: number; className?: string }>;
}

const NAV_LINKS: NavLink[] = [
  { href: "/admin", label: "Dashboard", icon: LayoutDashboard },
  { href: "/admin/orders", label: "Orders", icon: ShoppingBag },
  { href: "/admin/products", label: "Products", icon: Package },
  { href: "/admin/group-buy", label: "Group Buys", icon: Boxes },
  { href: "/admin/analytics", label: "Analytics", icon: BarChart2 },
  { href: "/admin/settings", label: "Settings", icon: Settings },
];

interface SidebarLinkProps {
  href: string;
  label: string;
  icon: React.ComponentType<{ size?: number; strokeWidth?: number; className?: string }>;
  currentPath: string;
}

function SidebarLink({ href, label, icon: Icon, currentPath }: SidebarLinkProps) {
  const active =
    href === "/admin" ? currentPath === "/admin" : currentPath.startsWith(href);

  return (
    <li>
      <Link
        href={href}
        aria-current={active ? "page" : undefined}
        className={cn(
          "flex items-center gap-3 px-4 py-3 rounded-[var(--radius-lg)]",
          "text-sm font-medium transition-all duration-150 select-none group",
          active
            ? "bg-[var(--color-accent-muted)] text-[var(--color-accent)] shadow-[var(--shadow-neu-raised-sm)]"
            : "text-[var(--color-text-secondary)] hover:bg-[var(--color-neu-bg-dark)] hover:text-[var(--color-text-primary)]",
        )}
      >
        <Icon
          size={18}
          strokeWidth={active ? 2.2 : 1.8}
          className="shrink-0"
        />
        <span>{label}</span>
      </Link>
    </li>
  );
}

