{
  "annotations": {
    "destructive_hint": false,
    "open_world_hint": true,
    "read_only_hint": false
  },
  "arguments": {
    "content": ""use server";

import { db } from "@/lib/db";
import { orders, orderEvents } from "@/lib/db/schema";
import { eq, sql } from "drizzle-orm";
import { auth } from "@/auth";
import {
  confirmPaymentSchema,
  rejectPaymentSchema,
  updateOrderStatusSchema,
  addOrderNoteSchema,
} from "@/lib/validation/schemas";
import { revalidatePath } from "next/cache";

async function requireAdmin() {
  const session = await auth();
  if (!session?.user) {
    throw new Error("Unauthorized");
  }
  return session;
}

const STATUS_LABELS: Record<string, string> = {
  pending_payment: "Pending Payment",
  payment_verification: "Payment Verification",
  paid: "Paid",
  processing: "Processing",
  ready_to_ship: "Ready to Ship",
  shipped: "Shipped",
  completed: "Completed",
  cancelled: "Cancelled",
};

// ============================================================
// CONFIRM PAYMENT
// ============================================================

export async function confirmPayment(
  formData: FormData
): Promise<{ success: boolean; error?: string }> {
  await requireAdmin();

  const parsed = confirmPaymentSchema.safeParse({
    orderId: Number(formData.get("orderId")),
  });
  if (!parsed.success) return { success: false, error: "Invalid request." };

  const { orderId } = parsed.data;

  const order = await db.query.orders.findFirst({
    where: (o, { eq }) => eq(o.id, orderId),
  });

  if (!order) return { success: false, error: "Order not found." };

  if (order.storefrontKey === "tindahan") {
    try {
      await db.execute(sql`SELECT confirm_tindahan_payment(${orderId})`);
    } catch (error: any) {
      const message = String(error?.message || "");
      if (message.includes("ON_HAND_STOCK_INSUFFICIENT")) {
        return { success: false, error: "Payment not confirmed. On-hand stock is no longer sufficient." };
      }
      console.error("Tindahan payment confirmation failed:", error);
      return { success: false, error: "Payment could not be confirmed. Check the group-buy migration and try again." };
    }

    revalidatePath("/");
    revalidatePath("/admin");
    revalidatePath("/admin/orders");
    revalidatePath("/admin/group-buy");
    revalidatePath("/admin/group-buy/orders");
    revalidatePath(`/admin/orders/${orderId}`);
    return { success: true };
  }

  // Update order status
  await db
    .update(orders)
    .set({
      paymentStatus: "paid",
      orderStatus: "processing",
      updatedAt: new Date(),
    })
    .where(eq(orders.id, orderId));

  // Log timeline events
  await db.insert(orderEvents).values([
    {
      orderId,
      eventType: "payment_confirmed",
      description: "Payment confirmed by seller.",
    },
    {
      orderId,
      eventType: "order_processing",
      description: "Order is now being processed.",
    },
  ]);

  revalidatePath("/");
  revalidatePath("/admin");
  revalidatePath("/admin/orders");
  revalidatePath(`/admin/orders/${orderId}`);

  return { success: true };
}

// ============================================================
// REJECT PAYMENT
// ============================================================

export async function rejectPayment(
  formData: FormData
): Promise<{ success: boolean; error?: string }> {
  await requireAdmin();

  const parsed = rejectPaymentSchema.safeParse({
    orderId: Number(formData.get("orderId")),
    reason: formData.get("reason") as string | undefined,
  });
  if (!parsed.success) return { success: false, error: "Invalid request." };

  const { orderId, reason } = parsed.data;

  // Update order status
  await db
    .update(orders)
    .set({
      paymentStatus: "rejected",
      orderStatus: "pending_payment",
      rejectionReason: reason || null,
      updatedAt: new Date(),
    })
    .where(eq(orders.id, orderId));

  // Log timeline event
  await db.insert(orderEvents).values({
    orderId,
    eventType: "payment_rejected",
    description: reason
      ? `Payment rejected. Reason: ${reason}`
      : "Payment rejected by seller.",
  });

  revalidatePath("/");
  revalidatePath("/admin");
  revalidatePath("/admin/orders");
  revalidatePath(`/admin/orders/${orderId}`);

  return { success: true };
}

// ============================================================
// UPDATE ORDER STATUS (Form & Direct)
// ============================================================

export async function updateOrderStatus(
  formData: FormData
): Promise<{ success: boolean; error?: string }> {
  await requireAdmin();

  const rawNotes = formData.get("notes");
  const notes =
    rawNotes && typeof rawNotes === "string" && rawNotes.trim() !== ""
      ? rawNotes.trim()
      : undefined;

  const parsed = updateOrderStatusSchema.safeParse({
    orderId: Number(formData.get("orderId")),
    orderStatus: formData.get("orderStatus"),
    notes,
  });
  if (!parsed.success) {
    console.error("updateOrderStatus validation failure:", parsed.error.format());
    return { success: false, error: "Invalid status or parameters." };
  }

  const { orderId, orderStatus } = parsed.data;

  return quickChangeOrderStatus(orderId, orderStatus, notes);
}

export async function quickChangeOrderStatus(
  orderId: number,
  orderStatus: string,
  notes?: string
): Promise<{ success: boolean; error?: string }> {
  await requireAdmin();

  const currentOrder = await db.query.orders.findFirst({ where: eq(orders.id, orderId) });
  if (!currentOrder) return { success: false, error: "Order not found." };
  if (
    currentOrder.storefrontKey === "tindahan" &&
    currentOrder.paymentStatus !== "paid" &&
    (orderStatus === "paid" || orderStatus === "processing")
  ) {
    return { success: false, error: "Verify the receipt before marking this order paid." };
  }

  const updateData: Record<string, any> = {
    orderStatus,
    updatedAt: new Date(),
  };

  if (notes !== undefined) {
    updateData.notes = notes;
  }

  if (orderStatus === "paid" || orderStatus === "processing") {
    updateData.paymentStatus = "paid";
  }

  await db.update(orders).set(updateData).where(eq(orders.id, orderId));

  await db.insert(orderEvents).values({
    orderId,
    eventType: `status_updated_${orderStatus}`,
    description: `Order status updated to: ${STATUS_LABELS[orderStatus] ?? orderStatus}.`,
  });

  revalidatePath("/");
  revalidatePath("/admin");
  revalidatePath("/admin/orders");
  revalidatePath(`/admin/orders/${orderId}`);

  return { success: true };
}

// ============================================================
// ADD INTERNAL NOTE
// ============================================================

export async function addOrderNote(
  formData: FormData
): Promise<{ success: boolean; error?: string }> {
  await requireAdmin();

  const parsed = addOrderNoteSchema.safeParse({
    orderId: Number(formData.get("orderId")),
    note: formData.get("note"),
  });
  if (!parsed.success) return { success: false, error: "Invalid note." };

  const { orderId, note } = parsed.data;

  await db
    .update(orders)
    .set({ notes: note, updatedAt: new Date() })
    .where(eq(orders.id, orderId));

  revalidatePath("/");
  revalidatePath(`/admin/orders/${orderId}`);
  return { success: true };
}

// ============================================================
// DELETE ORDER
// ============================================================

export async function deleteOrder(
  orderId: number
): Promise<{ success: boolean; error?: string }> {
  await requireAdmin();

  const order = await db.query.orders.findFirst({
    where: eq(orders.id, orderId),
  });

  if (!order) {
    return { success: false, error: "Order not found." };
  }

  await db.delete(orders).where(eq(orders.id, orderId));

  revalidatePath("/");
  revalidatePath("/admin");
  revalidatePath("/admin/orders");

  return { success: true };
}

