  },
  "arguments": {
    "content": ""use server";

import { auth } from "@/auth";
import { db } from "@/lib/db";
import { categories, groupBuyBatches, products, orderShipments, orderEvents } from "@/lib/db/schema";
import { eq, desc, and } from "drizzle-orm";
import { revalidatePath } from "next/cache";

async function requireAdmin() {
  const session = await auth();
  if (!session?.user) throw new Error("Unauthorized");
}

function slug(value: string) {
  return value.toLowerCase().trim().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "") || "item";
}

function refresh() {
  revalidatePath("/admin/group-buy");
  revalidatePath("/api/products");
}

export async function createTindahanCategory(formData: FormData) {
  await requireAdmin();
  const name = String(formData.get("name") || "").trim();
  if (!name || name.length > 60) throw new Error("Category name must be 1 to 60 characters.");
  const base = `tindahan-${slug(name)}`;
  const found = await db.query.categories.findFirst({ where: eq(categories.id, base) });
  const id = found ? `${base}-${Date.now().toString(36)}` : base;
  const last = await db.query.categories.findFirst({ orderBy: [desc(categories.sortOrder)] });
  await db.insert(categories).values({
    id,
    storefrontKey: "tindahan",
    name,
    icon: String(formData.get("icon") || "📦").slice(0, 8),
    pill: String(formData.get("pill") || "").slice(0, 30),
    sortOrder: (last?.sortOrder ?? 0) + 1,
    isActive: true,
  });
  refresh();
}

export async function saveTindahanProduct(formData: FormData) {
  await requireAdmin();
  const id = String(formData.get("id") || "").trim();
  const categoryId = String(formData.get("categoryId") || "").trim();
  const name = String(formData.get("name") || "").trim();
  const fullName = String(formData.get("fullName") || "").trim();
