    "content": ""use server";

import { db } from "@/lib/db";
import { categories, products } from "@/lib/db/schema";
import { eq, desc, and } from "drizzle-orm";
import { revalidatePath } from "next/cache";
import { auth } from "@/auth";

function slugify(text: string): string {
  return text
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-|-$)/g, "");
}

/**
 * Creates a new category in the catalog
 */
export async function createCategoryAction(data: {
  name: string;
  icon: string;
  pill?: string;
}) {
  try {
    const session = await auth();
    if (!session) {
      return { success: false, error: "Unauthorized" };
    }

    if (!data.name || data.name.trim() === "") {
      return { success: false, error: "Category name is required" };
    }

    const baseSlug = slugify(data.name);
    let categoryId = baseSlug;

    // Check if category ID already exists
    const existing = await db.query.categories.findFirst({
      where: eq(categories.id, categoryId),
    });

    if (existing) {
      categoryId = `${baseSlug}-${Date.now().toString(36)}`;
    }

    // Get current max sortOrder
    const latestCat = await db.query.categories.findFirst({
      orderBy: [desc(categories.sortOrder)],
    });
    const sortOrder = (latestCat?.sortOrder ?? 0) + 1;

    await db.insert(categories).values({
      id: categoryId,
      name: data.name.trim(),
      icon: data.icon?.trim() || "💉",
      pill: data.pill?.trim() || "",
      sortOrder,
      isActive: true,
    });

    revalidatePath("/admin/products");
    revalidatePath("/api/products");

    return { success: true, categoryId };
  } catch (error: any) {
    console.error("createCategoryAction error:", error);
    return { success: false, error: error?.message || "Failed to create category" };
  }
}

/**
 * Creates a new product under a category
 */
export async function createProductAction(data: {
  categoryId: string;
  name: string;
  fullName: string;
  price: number;
  emoji?: string;
}) {
  try {
    const session = await auth();
    if (!session) {
      return { success: false, error: "Unauthorized" };
    }

    if (!data.name || !data.fullName || !data.categoryId) {
      return { success: false, error: "Name, full name, and category are required" };
    }

    const category = await db.query.categories.findFirst({ where: eq(categories.id, data.categoryId) });
    if (!category || category.storefrontKey !== "main") {
      return { success: false, error: "Choose a PBC catalog category." };
    }

    const baseSlug = slugify(data.name).replace(/-/g, "_");
    let productId = baseSlug;

    // Check if product ID exists
    const existing = await db.query.products.findFirst({
      where: eq(products.id, productId),
    });

    if (existing) {
      productId = `${baseSlug}_${Date.now().toString(36)}`;
    }

    // Get current max sort order for this category
    const latestProd = await db.query.products.findFirst({
      where: eq(products.categoryId, data.categoryId),
      orderBy: [desc(products.sortOrder)],
    });
    const sortOrder = (latestProd?.sortOrder ?? 0) + 1;

    await db.insert(products).values({
      id: productId,
      categoryId: data.categoryId,
      name: data.name.trim(),
      fullName: data.fullName.trim(),
      price: Math.round(data.price),
      emoji: data.emoji?.trim() || "💉",
      isAvailable: true,
      sortOrder,
    });

    revalidatePath("/admin/products");
    revalidatePath("/api/products");

    return { success: true, productId };
  } catch (error: any) {
    console.error("createProductAction error:", error);
    return { success: false, error: error?.message || "Failed to create product" };
  }
}

/**
 * Updates an existing product's details
 */
export async function updateProductAction(
  id: string,
  data: {
    categoryId: string;
    name: string;
    fullName: string;
    price: number;
    emoji?: string;
  }
) {
  try {
    const session = await auth();
    if (!session) {
      return { success: false, error: "Unauthorized" };
    }

    const [existing, category] = await Promise.all([
      db.query.products.findFirst({ where: eq(products.id, id) }),
      db.query.categories.findFirst({ where: eq(categories.id, data.categoryId) }),
    ]);
    if (existing?.storefrontKey !== "main" || category?.storefrontKey !== "main") {
      return { success: false, error: "Choose a PBC catalog product and category." };
    }

    await db
      .update(products)
      .set({
        categoryId: data.categoryId,
        name: data.name.trim(),
        fullName: data.fullName.trim(),
        price: Math.round(data.price),
        emoji: data.emoji?.trim() || "💉",
      })
      .where(and(eq(products.id, id), eq(products.storefrontKey, "main")));

    revalidatePath("/admin/products");
    revalidatePath("/api/products");

    return { success: true };
  } catch (error: any) {
    console.error("updateProductAction error:", error);
    return { success: false, error: error?.message || "Failed to update product" };
  }
}

/**
 * Deletes a product permanently
 */
export async function deleteProductAction(id: string) {
  try {
    const session = await auth();
    if (!session) {
      return { success: false, error: "Unauthorized" };
    }

    await db.delete(products).where(and(eq(products.id, id), eq(products.storefrontKey, "main")));

    revalidatePath("/admin/products");
    revalidatePath("/api/products");

    return { success: true };
  } catch (error: any) {
    console.error("deleteProductAction error:", error);
    return { success: false, error: error?.message || "Failed to delete product" };
  }
}

/**
 * Toggles product availability between in-stock and out-of-stock
 */
export async function toggleProductAvailability(
  id: string,
  currentStatus: boolean
) {
  try {
    const session = await auth();
    if (!session) {
      return { success: false, error: "Unauthorized" };
    }

    const newStatus = !currentStatus;

    await db
      .update(products)
      .set({ isAvailable: newStatus })
      .where(and(eq(products.id, id), eq(products.storefrontKey, "main")));

    revalidatePath("/admin/products");
    revalidatePath("/api/products");

    return { success: true, isAvailable: newStatus };
  } catch (error: any) {
    console.error("toggleProductAvailability error:", error);
    return {
      success: false,
      error: error?.message || "Failed to toggle product availability",
    };
  }
}
