  text,
  integer,
  boolean,
  timestamp,
  pgEnum,
  index,
  unique,
  jsonb,
} from "drizzle-orm/pg-core";
import { relations } from "drizzle-orm";

// ============================================================
// ENUMS
// ============================================================

export const paymentStatusEnum = pgEnum("payment_status", [
  "pending",
  "under_verification",
  "paid",
  "rejected",
]);

export const orderStatusEnum = pgEnum("order_status", [
  "pending_payment",
  "payment_verification",
  "paid",
  "processing",
  "ready_to_ship",
  "shipped",
  "completed",
  "cancelled",
]);

export const userRoleEnum = pgEnum("user_role", ["admin", "staff"]);
export const storefrontKeyEnum = pgEnum("storefront_key", ["main", "tindahan"]);
export const productKindEnum = pgEnum("product_kind", ["standard", "on_hand", "group_buy"]);
export const groupBuyBatchStatusEnum = pgEnum("group_buy_batch_status", [
  "open",
  "closed",
  "ordered",
  "arrived",
]);
export const shipmentKindEnum = pgEnum("shipment_kind", ["combined", "on_hand", "group_buy"]);
export const shipmentStatusEnum = pgEnum("shipment_status", [
  "processing",
  "ready_to_ship",
  "shipped",
  "completed",
]);

// ============================================================
// CATEGORIES
// ============================================================

export const categories = pgTable(
  "categories",
  {
    id: text("id").primaryKey(), // slugified name, e.g. "tirzepatide-complete-set"
    storefrontKey: storefrontKeyEnum("storefront_key").notNull().default("main"),
    name: text("name").notNull(),
    icon: text("icon").default("💉"),
    pill: text("pill").default(""),
    sortOrder: integer("sort_order").default(0),
    isActive: boolean("is_active").default(true),
    createdAt: timestamp("created_at").defaultNow(),
  },
  (t) => [
    index("categories_sort_order_idx").on(t.sortOrder),
    index("categories_is_active_idx").on(t.isActive),
  ]
);

// ============================================================
// GROUP BUY BATCHES
// ============================================================

export const groupBuyBatches = pgTable(
  "group_buy_batches",
  {
    id: serial("id").primaryKey(),
    name: text("name").notNull(),
    status: groupBuyBatchStatusEnum("status").notNull().default("open"),
    deadline: timestamp("deadline", { withTimezone: true }).notNull(),
    eta: timestamp("eta", { withTimezone: true }),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index("group_buy_batches_status_deadline_idx").on(t.status, t.deadline)]
);

// ============================================================
// PRODUCTS
// ============================================================

export const products = pgTable(
  "products",
  {
    id: text("id").primaryKey(), // e.g., "tir10_set"
    storefrontKey: storefrontKeyEnum("storefront_key").notNull().default("main"),
    kind: productKindEnum("kind").notNull().default("standard"),
    batchId: integer("batch_id").references(() => groupBuyBatches.id, { onDelete: "set null" }),
    categoryId: text("category_id").references(() => categories.id, {
      onDelete: "cascade",
    }),
    name: text("name").notNull(),
    fullName: text("full_name").notNull(),
    price: integer("price").notNull(),
    compareAtPrice: integer("compare_at_price"),
    description: text("description"),
    imageUrl: text("image_url"),
    stock: integer("stock").notNull().default(0),
    emoji: text("emoji").default("💉"),
    isAvailable: boolean("is_available").default(true),
    sortOrder: integer("sort_order").default(0),
    createdAt: timestamp("created_at").defaultNow(),
  },
  (t) => [
    index("products_category_id_idx").on(t.categoryId),
    index("products_storefront_kind_idx").on(t.storefrontKey, t.kind),
    index("products_batch_id_idx").on(t.batchId),
    index("products_is_available_idx").on(t.isAvailable),
    index("products_sort_order_idx").on(t.sortOrder),
  ]
);

// ============================================================
// APP SETTINGS
// ============================================================

export const appSettings = pgTable("app_settings", {
  key: text("key").primaryKey(), // e.g., "shipping_config"
  value: jsonb("value").notNull(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// ============================================================
// SHIPPING METHODS (Legacy support)
// ============================================================

export const shippingMethods = pgTable("shipping_methods", {
  id: serial("id").primaryKey(),
  name: text("name").notNull(),
  fee: integer("fee").notNull(), // cents
  isActive: boolean("is_active").notNull().default(true),
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
});

// ============================================================
// ORDERS
// ============================================================

export const orders = pgTable(
  "orders",
  {
    id: serial("id").primaryKey(),
    orderNumber: text("order_number").notNull(),
    storefrontKey: storefrontKeyEnum("storefront_key").notNull().default("main"),
    shipmentPreference: text("shipment_preference"),
    // Customer info (snapshot at time of order)
    customerName: text("customer_name").notNull(),
    customerPhone: text("customer_phone").notNull(),
    customerEmail: text("customer_email"),
    // Delivery
    deliveryAddress: text("delivery_address").notNull(),
    city: text("city").notNull(),
    province: text("province").notNull(),
    postalCode: text("postal_code"),
    shippingMethod: text("shipping_method").notNull(),
    shippingFee: integer("shipping_fee").notNull().default(0), // cents
    // Payment
    paymentMethod: text("payment_method").notNull(),
    paymentProofFileId: text("payment_proof_file_id"), // Google Drive file ID
    paymentStatus: paymentStatusEnum("payment_status").notNull().default("pending"),
    // Order
    orderStatus: orderStatusEnum("order_status").notNull().default("pending_payment"),
    // Financials (all in cents)
    subtotal: integer("subtotal").notNull(),
    total: integer("total").notNull(),
    // Internal
    notes: text("notes"),
    rejectionReason: text("rejection_reason"),
    createdAt: timestamp("created_at").notNull().defaultNow(),
    updatedAt: timestamp("updated_at").notNull().defaultNow(),
  },
  (t) => [
    unique("orders_order_number_unique").on(t.orderNumber),
    index("orders_order_number_idx").on(t.orderNumber),
    index("orders_customer_phone_idx").on(t.customerPhone),
    index("orders_customer_name_idx").on(t.customerName),
    index("orders_payment_status_idx").on(t.paymentStatus),
    index("orders_order_status_idx").on(t.orderStatus),
    index("orders_created_at_idx").on(t.createdAt),
  ]
);

// ============================================================
// ORDER SHIPMENTS
// ============================================================

export const orderShipments = pgTable(
  "order_shipments",
  {
    id: serial("id").primaryKey(),
    orderId: integer("order_id").notNull().references(() => orders.id, { onDelete: "cascade" }),
    kind: shipmentKindEnum("kind").notNull(),
    batchId: integer("batch_id").references(() => groupBuyBatches.id, { onDelete: "set null" }),
    shippingFee: integer("shipping_fee").notNull().default(0),
    status: shipmentStatusEnum("status").notNull().default("processing"),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index("order_shipments_order_id_idx").on(t.orderId)]
);

// ============================================================
// ORDER ITEMS (price snapshot)
// ============================================================

export const orderItems = pgTable(
  "order_items",
  {
    id: serial("id").primaryKey(),
    orderId: integer("order_id")
      .notNull()
      .references(() => orders.id, { onDelete: "cascade" }),
    productId: text("product_id"),
    productKind: productKindEnum("product_kind").notNull().default("standard"),
    batchId: integer("batch_id").references(() => groupBuyBatches.id, { onDelete: "set null" }),
    shipmentId: integer("shipment_id").references(() => orderShipments.id, { onDelete: "set null" }),
    // Price snapshot — historical prices preserved even if product changes
    productName: text("product_name").notNull(),
    unitPrice: integer("unit_price").notNull(), // cents
    quantity: integer("quantity").notNull(),
    subtotal: integer("subtotal").notNull(), // unit_price * quantity in cents
    createdAt: timestamp("created_at").notNull().defaultNow(),
  },
  (t) => [
    index("order_items_order_id_idx").on(t.orderId),
    index("order_items_product_id_idx").on(t.productId),
  ]
);

// ============================================================
// ORDER EVENTS (timeline)
// ============================================================

export const orderEvents = pgTable(
  "order_events",
  {
    id: serial("id").primaryKey(),
    orderId: integer("order_id")
      .notNull()
      .references(() => orders.id, { onDelete: "cascade" }),
    eventType: text("event_type").notNull(), // e.g. "order_submitted", "payment_confirmed"
    description: text("description"),
    createdAt: timestamp("created_at").notNull().defaultNow(),
  },
  (t) => [index("order_events_order_id_idx").on(t.orderId)]
);

// ============================================================
// USERS (admin/staff)
// ============================================================

export const users = pgTable(
  "users",
  {
    id: serial("id").primaryKey(),
    email: text("email").notNull(),
    passwordHash: text("password_hash").notNull(),
    name: text("name").notNull(),
    role: userRoleEnum("role").notNull().default("admin"),
    createdAt: timestamp("created_at").notNull().defaultNow(),
    updatedAt: timestamp("updated_at").notNull().defaultNow(),
  },
  (t) => [
    unique("users_email_unique").on(t.email),
    index("users_email_idx").on(t.email),
  ]
);

// ============================================================
// PUSH SUBSCRIPTIONS
// ============================================================

export const pushSubscriptions = pgTable(
  "push_subscriptions",
  {
    id: serial("id").primaryKey(),
    endpoint: text("endpoint").notNull(),
    p256dh: text("p256dh").notNull(),
    auth: text("auth").notNull(),
    userAgent: text("user_agent"),
    createdAt: timestamp("created_at").notNull().defaultNow(),
    updatedAt: timestamp("updated_at").notNull().defaultNow(),
  },
  (t) => [unique("push_subscriptions_endpoint_key").on(t.endpoint)]
);

// ============================================================
// DRIZZLE RELATIONS
// ============================================================

export const categoriesRelations = relations(categories, ({ many }) => ({
  products: many(products),
}));

export const groupBuyBatchesRelations = relations(groupBuyBatches, ({ many }) => ({
  products: many(products),
  orderItems: many(orderItems),
  shipments: many(orderShipments),
}));

export const productsRelations = relations(products, ({ one }) => ({
  category: one(categories, {
    fields: [products.categoryId],
    references: [categories.id],
  }),
  batch: one(groupBuyBatches, {
    fields: [products.batchId],
    references: [groupBuyBatches.id],
  }),
}));

export const ordersRelations = relations(orders, ({ many }) => ({
  orderItems: many(orderItems),
  orderEvents: many(orderEvents),
  shipments: many(orderShipments),
}));

export const orderShipmentsRelations = relations(orderShipments, ({ one, many }) => ({
  order: one(orders, {
    fields: [orderShipments.orderId],
    references: [orders.id],
  }),
  batch: one(groupBuyBatches, {
    fields: [orderShipments.batchId],
    references: [groupBuyBatches.id],
  }),
  items: many(orderItems),
}));

export const orderItemsRelations = relations(orderItems, ({ one }) => ({
  order: one(orders, {
    fields: [orderItems.orderId],
    references: [orders.id],
  }),
  batch: one(groupBuyBatches, {
    fields: [orderItems.batchId],
    references: [groupBuyBatches.id],
  }),
  shipment: one(orderShipments, {
    fields: [orderItems.shipmentId],
    references: [orderShipments.id],
  }),
}));

export const orderEventsRelations = relations(orderEvents, ({ one }) => ({
  order: one(orders, {
    fields: [orderEvents.orderId],
    references: [orders.id],
  }),
}));

// ============================================================
// TYPE EXPORTS
// ============================================================

export type Category = typeof categories.$inferSelect;
export type NewCategory = typeof categories.$inferInsert;
export type Product = typeof products.$inferSelect;
export type NewProduct = typeof products.$inferInsert;
export type GroupBuyBatch = typeof groupBuyBatches.$inferSelect;
export type NewGroupBuyBatch = typeof groupBuyBatches.$inferInsert;
export type OrderShipment = typeof orderShipments.$inferSelect;
export type NewOrderShipment = typeof orderShipments.$inferInsert;
export type AppSetting = typeof appSettings.$inferSelect;
export type NewAppSetting = typeof appSettings.$inferInsert;

export type Order = typeof orders.$inferSelect;
export type NewOrder = typeof orders.$inferInsert;
export type OrderItem = typeof orderItems.$inferSelect;
export type NewOrderItem = typeof orderItems.$inferInsert;
export type OrderEvent = typeof orderEvents.$inferSelect;
export type User = typeof users.$inferSelect;
export type ShippingMethod = typeof shippingMethods.$inferSelect;
export type PushSubscriptionRecord = typeof pushSubscriptions.$inferSelect;
export type NewPushSubscriptionRecord = typeof pushSubscriptions.$inferInsert;

export type PaymentStatus = (typeof paymentStatusEnum.enumValues)[number];
export type OrderStatus = (typeof orderStatusEnum.enumValues)[number];
export type StorefrontKey = (typeof storefrontKeyEnum.enumValues)[number];
export type ProductKind = (typeof productKindEnum.enumValues)[number];
export type GroupBuyBatchStatus = (typeof groupBuyBatchStatusEnum.enumValues)[number];

export type OrderWithItems = Order & {
  orderItems: OrderItem[];
  orderEvents: OrderEvent[];
};
