export type OrderEvent = typeof orderEvents.$inferSelect;
export type User = typeof users.$inferSelect;
export type ShippingMethod = typeof shippingMethods.$inferSelect;
export type PushSubscriptionRecord = typeof pushSubscriptions.$inferSelect;
export type NewPushSubscriptionRecord = typeof pushSubscriptions.$inferInsert;

export type PaymentStatus = (typeof paymentStatusEnum.enumValues)[number];
export type OrderStatus = (typeof orderStatusEnum.enumValues)[number];
export type StorefrontKey = (typeof storefrontKeyEnum.enumValues)[number];
export type ProductKind = (typeof productKindEnum.enumValues)[number];
export type GroupBuyBatchStatus = (typeof groupBuyBatchStatusEnum.enumValues)[number];

export type OrderWithItems = Order & {
